import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class QueuePipelineTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    /** Runs drain on a daemon thread so a deadlocked solution reports a clean FAIL. */
    static List<String> guarded(List<String> items) {
        final List<List<String>> box = new ArrayList<>();
        Thread runner = new Thread(() -> {
            try {
                box.add(QueuePipeline.drain(items));
            } catch (Throwable t) {
                // leave the box empty -- the caller reports it as a failure
            }
        });
        runner.setDaemon(true);
        runner.start();
        try {
            runner.join(3000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return box.isEmpty() ? null : box.get(0);
    }

    static String text(List<String> values) {
        return values == null ? "no result (drain blocked or threw)" : values.toString();
    }

    public static void main(String[] args) {
        check("drain uppercases in order", "[A, B, C]",
                text(guarded(Arrays.asList("a", "b", "c"))));
        check("an empty job list drains to an empty list", "[]",
                text(guarded(new ArrayList<String>())));
        check("a single item", "[SOLO]", text(guarded(Arrays.asList("solo"))));
        check("already uppercase values are unchanged", "[X, Y]",
                text(guarded(Arrays.asList("X", "y"))));
        check("an empty string is still real work", "[, Z]",
                text(guarded(Arrays.asList("", "z"))));

        List<String> many = new ArrayList<>();
        for (int i = 0; i < 100; i++) {
            many.add("job" + i);
        }
        List<String> manyOut = guarded(many);
        check("100 items pass through a capacity-2 queue", 100,
                manyOut == null ? -1 : manyOut.size());
        boolean haveMany = manyOut != null && !manyOut.isEmpty();
        check("first of the 100", "JOB0", haveMany ? manyOut.get(0) : "none");
        check("last of the 100", "JOB99",
                haveMany ? manyOut.get(manyOut.size() - 1) : "none");

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
        System.exit(0);
    }
}

