import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;

/**
 * TASK: Move work between two threads through a BlockingQueue, ending with a poison pill.
 *
 * drain(items) must:
 *   1. create a BlockingQueue<String> with capacity 2 (small on purpose -- the
 *      producer really will have to wait for the consumer),
 *   2. start a PRODUCER thread that put()s every item in order and then put()s
 *      the POISON constant exactly once,
 *   3. start a CONSUMER thread that take()s in a loop, stops as soon as it sees
 *      POISON, and collects every other value UPPERCASED into a list,
 *   4. join BOTH threads,
 *   5. return the consumer's list.
 *
 * POISON is the agreed "no more work" marker; it is never part of the result.
 * Compare it with == or equals, but do NOT put it in the output list.
 *
 * Example: drain(List.of("a", "b")) -> ["A", "B"]
 *          drain(List.of())         -> []   (the producer still sends POISON)
 */
public class QueuePipeline {

    public static final String POISON = "__END_OF_WORK__";

    public static List<String> drain(List<String> items) throws InterruptedException {
        BlockingQueue<String> queue = new ArrayBlockingQueue<>(2);
        List<String> collected = new ArrayList<>();

        Thread producer = new Thread(() -> {
            try {
                for (String item : items) {
                    queue.put(item);
                }
                queue.put(POISON);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        Thread consumer = new Thread(() -> {
            try {
                while (true) {
                    String next = queue.take();
                    if (POISON.equals(next)) {
                        return;
                    }
                    collected.add(next.toUpperCase(java.util.Locale.ROOT));
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        producer.start();
        consumer.start();
        producer.join();
        consumer.join();
        return collected;
    }
}
